        Lease.objects.filter(property_id=prop.pk, unit__isnull=True).update(unit_id=unit.pk)
        RentalApplication.objects.filter(property_id=prop.pk, unit__isnull=True).update(unit_id=unit.pk)
        MaintenanceRequest.objects.filter(property_id=prop.pk, unit__isnull=True).update(unit_id=unit.pk)
